-- Aquavia: German, French and Russian product texts. Schema AND data. GENERATED by
-- scripts/generate-product-seed.ts; don't edit by hand. Run after 0002.
-- Safe to re-run.
--
-- 1. Adds twin columns for the translated texts: tagline_de, description_de,
--    tagline_fr, description_fr, tagline_ru, description_ru. Spec rows (in the specs JSON) get
--    group_de / label_de / value_de keys and the same for _fr and _ru.
-- 2. Fills them in from the site's starting translations, matched on the
--    English text. A product whose English the client has rewritten keeps
--    blank translations (the site shows the English until they're written in
--    /admin), and nothing already translated is overwritten.

alter table public.products
  add column if not exists tagline_de text,
  add column if not exists description_de text,
  add column if not exists tagline_fr text,
  add column if not exists description_fr text,
  add column if not exists tagline_ru text,
  add column if not exists description_ru text;

-- One statement, with the translations inline: no temporary table, which the
-- Supabase SQL editor doesn't keep between statements.
with m as (select $data${
 "de": {
  "AstralPool's design-led automatic slatted cover for pools up to 7.5 × 15 m.": "Die designorientierte automatische Lamellenabdeckung von AstralPool für Pools bis 7,5 × 15 m.",
  "Octéo is an above-ground automatic slatted cover. The roller sits on the pool deck between two sculpted cast-aluminium legs that house the 24 V motor, and the cover glides over the water at the turn of a key or from your phone. It keeps the pool clean, reduces heat loss and evaporation, and secures the pool to the French NF P90-308 safety standard. Choose from four leg finishes and four slat colours, with optional solar-powered LED lighting in both legs.": "Octéo ist eine automatische Lamellenabdeckung über dem Wasser. Die Rolle steht auf dem Beckenrand zwischen zwei skulpturalen Füßen aus Aluminiumguss, die den 24-V-Motor beherbergen, und die Abdeckung gleitet per Schlüsseldreh oder Smartphone über das Wasser. Sie hält den Pool sauber, verringert Wärmeverlust und Verdunstung und sichert den Pool nach der französischen Sicherheitsnorm NF P90-308. Wählen Sie aus vier Fußausführungen und vier Lamellenfarben, optional mit solarbetriebener LED-Beleuchtung in beiden Füßen.",
