}$data$::jsonb as tr)
update public.products p set
  tagline_de = coalesce(nullif(p.tagline_de, ''), m.tr->'de'->>p.tagline),
  description_de = coalesce(nullif(p.description_de, ''), m.tr->'de'->>p.description),
  tagline_fr = coalesce(nullif(p.tagline_fr, ''), m.tr->'fr'->>p.tagline),
  description_fr = coalesce(nullif(p.description_fr, ''), m.tr->'fr'->>p.description),
  tagline_ru = coalesce(nullif(p.tagline_ru, ''), m.tr->'ru'->>p.tagline),
  description_ru = coalesce(nullif(p.description_ru, ''), m.tr->'ru'->>p.description),
  specs = case when jsonb_array_length(p.specs) = 0 then p.specs else (
    select jsonb_agg(e || jsonb_strip_nulls(jsonb_build_object(
      'group_de', coalesce(nullif(e->>'group_de', ''), m.tr->'de'->>(e->>'group')),
      'label_de', coalesce(nullif(e->>'label_de', ''), m.tr->'de'->>(e->>'label')),
      'value_de', coalesce(nullif(e->>'value_de', ''), m.tr->'de'->>(e->>'value')),
      'group_fr', coalesce(nullif(e->>'group_fr', ''), m.tr->'fr'->>(e->>'group')),
      'label_fr', coalesce(nullif(e->>'label_fr', ''), m.tr->'fr'->>(e->>'label')),
      'value_fr', coalesce(nullif(e->>'value_fr', ''), m.tr->'fr'->>(e->>'value')),
      'group_ru', coalesce(nullif(e->>'group_ru', ''), m.tr->'ru'->>(e->>'group')),
      'label_ru', coalesce(nullif(e->>'label_ru', ''), m.tr->'ru'->>(e->>'label')),
      'value_ru', coalesce(nullif(e->>'value_ru', ''), m.tr->'ru'->>(e->>'value'))
    )) order by i)
    from jsonb_array_elements(p.specs) with ordinality as s(e, i)
  ) end
from m;

select
  count(*) filter (where description_de is not null) as translated_de,
  count(*) filter (where description_fr is not null) as translated_fr,
  count(*) filter (where description_ru is not null) as translated_ru,
  count(*) as products
from public.products;
